<?php
namespace App\Http\Middleware; use App\Models\AuditLog; use Closure; use Illuminate\Http\Request; use Illuminate\Support\Str; use Symfony\Component\HttpFoundation\Response;
class AuditRequest {public function handle(Request $request,Closure $next):Response{$requestId=$request->header('X-Request-Id',(string)Str::uuid());$response=$next($request);$response->headers->set('X-Request-Id',$requestId);if(in_array($request->method(),['POST','PUT','PATCH','DELETE'])&&$request->user()){AuditLog::create(['user_id'=>$request->user()->id,'company_id'=>$request->input('company_id'),'action'=>$request->method().' '.$request->route()?->uri(),'entity_type'=>$request->route()?->getName(),'entity_id'=>$request->route('id')??$request->route('batch')??$request->route('version'),'ip_address'=>$request->ip(),'user_agent'=>mb_substr((string)$request->userAgent(),0,1000),'request_id'=>$requestId,'metadata'=>['status'=>$response->getStatusCode()]]);}return $response;}}
